interface.definition:
#"SYSTEM_SYSRULES_cardLayout"(         
  contents: {
    /*SAVE AND EXIT VALIDATION*/
    #"SYSTEM_SYSRULES_sideBySideLayout"(              
      items: {
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextIcon"(
                icon: "exclamation-circle",
                color: "#f1c232",
                size: "MEDIUM"
              )
            }
          ),
          width: "MINIMIZE"
        ),
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: {
                  "Please complete all minimum required fields in the nomination details tab to save this nomination"
                },
                color: "#f1c232",
                size: "MEDIUM",
                style: {
                  "STRONG"
                }
              )
            }
          )
        )
      },
      alignVertical: "MIDDLE",
      showWhen: ri!validateNominationDetailsTabSaveAndExit = false,
      spacing: "STANDARD"
    ),
    /*SUBMIT VALIDATION*/
    #"SYSTEM_SYSRULES_sideBySideLayout"(              
      items: {
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextIcon"(
                icon: "exclamation-circle",
                color: "#f1c232",
                size: "MEDIUM"
              )
            }
          ),
          width: "MINIMIZE"
        ),
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: {
                  "Please complete all required fields in the nomination details tab to submit this nomination"
                },
                color: "#f1c232",
                size: "MEDIUM",
                style: {
                  "STRONG"
                }
              )
            }
          )
        )
      },
      alignVertical: "MIDDLE",
      showWhen: ri!validateNominationDetailsTabSubmit = false,
      spacing: "STANDARD"
    ),
    /*REVIEW/TASK DPP OPTIONS*/
    #"SYSTEM_SYSRULES_sideBySideLayout"(              
      items: {
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextIcon"(
                icon: "exclamation-circle",
                color: "#f1c232",
                size: "MEDIUM"
              )
            }
          ),
          width: "MINIMIZE"
        ),
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {                      
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: {
                  "Please select an option from the due diligence tab, interview/office visit tab, or the approver selection tab to submit this nomination"
                },
                color: "#f1c232",
                size: "MEDIUM",
                style: "STRONG"
              )                   
            }
          )
        )
      },
      alignVertical: "MIDDLE",
      showWhen: and(
        ri!isDueDiligenceComplete = false,
        ri!isInterviewOfficeSectionComplete = false,
        ri!isApproverSelectionComplete = false
      ),
      spacing: "STANDARD"
    ),
    /*EMPTY GROUP VALIDATION*/
    #"SYSTEM_SYSRULES_sideBySideLayout"(              
      items: {
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextIcon"(
                icon: "exclamation-circle",
                color: "#f1c232",
                size: "MEDIUM"
              )
            }
          ),
          width: "MINIMIZE"
        ),
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {                      
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: {
                  "Please select an option from the approver selection tab to submit this nomination"
                },
                color: "#f1c232",
                size: "MEDIUM",
                style: "STRONG"
              )                   
            }
          )
        )
      },
      alignVertical: "MIDDLE",
      showWhen: ri!isApproverSelectionCompleteIntl = true,
      spacing: "STANDARD"
    ),
    /*EMPTY GROUP VALIDATION*/
    #"SYSTEM_SYSRULES_sideBySideLayout"(              
      items: {
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextIcon"(
                icon: "exclamation-circle",
                color: "#f1c232",
                size: "MEDIUM"
              )
            }
          ),
          width: "MINIMIZE"
        ),
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {                      
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: {
                  "The selected reviewer group doesn't have a user associated to it, please select another reviewer"
                },
                color: "#f1c232",
                size: "MEDIUM",
                style: "STRONG"
              )                   
            }
          )
        )
      },
      alignVertical: "MIDDLE",
      showWhen: ri!emptyReviewerGroupValidation = false,
      spacing: "STANDARD"
    ),
    /*BU TO REVIEW COMMENTS TAB VALIDATION*/
    #"SYSTEM_SYSRULES_sideBySideLayout"(              
      items: {
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {
              #"SYSTEM_SYSRULES_richTextIcon"(
                icon: "exclamation-circle",
                color: "#f1c232",
                size: "MEDIUM"
              )
            }
          ),
          width: "MINIMIZE"
        ),
        #"SYSTEM_SYSRULES_sideBySideItem"(
          item: #"SYSTEM_SYSRULES_richTextDisplayField"(
            labelPosition: "COLLAPSED",
            value: {                      
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: {
                  "Please make sure to review all comments in the previous comments tab"
                },
                color: "#f1c232",
                size: "MEDIUM",
                style: "STRONG"
              )                   
            }
          )
        )
      },
      alignVertical: "MIDDLE",
      showWhen: ri!isBUReviewCommentsValidation = true,
      spacing: "STANDARD"
    )
  },
  showWhen: true,
  style: "NONE",
  marginBelow: "STANDARD",
  showBorder: false
)
